import re
from datetime import datetime, timedelta

_DISPLAY_NAME_RE = re.compile(r"<([^<>]*)>")
_PHONE_MARKER_RE = re.compile(r"ext|x|#")
_ZIP_PLUS4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_FIVE_DIGITS_RE = re.compile(r"[0-9]{5}")
_FOUR_DIGITS_RE = re.compile(r"[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_TRUE_VALUES = {"y", "yes", "true", "1"}


def _normalize_email(raw):
    s = (raw or "").strip()
    m = _DISPLAY_NAME_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    s = (raw or "").lower()
    m = _PHONE_MARKER_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(ch for ch in s if "0" <= ch <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = _ZIP_PLUS4_RE.fullmatch(s)
    if m:
        s = m.group(1)
    if _FOUR_DIGITS_RE.fullmatch(s):
        s = "0" + s
    return s if _FIVE_DIGITS_RE.fullmatch(s) else ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return datetime.min  # unparseable dates sort as oldest


def _ts_key(dt):
    # Exact integer form of a datetime, so it can be negated for "most recent first".
    return (dt - datetime.min) // timedelta(microseconds=1)


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw or "") if t.strip()}


def _best(members, field):
    """Pick the value of `field` from the best member with a non-empty value.
    Priority: source "manual", then most recent updated, then earliest input row."""
    cands = [m for m in members if m[field]]
    if not cands:
        return ""
    best = min(cands, key=lambda m: (not m["manual"], -_ts_key(m["ts"]), m["idx"]))
    return best[field]


def dedupe_contacts(rows):
    # 1. Normalize each row and drop rows with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email"))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone"))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        source = (row.get("source") or "").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(row.get("tags")),
            "opted_out": (row.get("opted_out") or "").strip().lower() in _TRUE_VALUES,
            "ts": _parse_updated(row.get("updated")),
        })

    # 2. Group matching rows with union-find (transitive matching).
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Groups are keyed in order of their earliest row, since i is visited ascending.
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(recs[i])

    # 3. Build one output record per person.
    out = []
    for members in groups.values():
        all_tags = set()
        for m in members:
            all_tags |= m["tags"]
        latest = max(m["ts"] for m in members)
        out.append({
            "first_name": _best(members, "first_name"),
            "last_name": _best(members, "last_name"),
            "zip": _best(members, "zip"),
            "email": _best(members, "email"),
            "phone": _best(members, "phone"),
            "source": _best(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return out
```

Notes:

- **Opt-outs stay in the output.** Per the spec, opted-out people are returned with `opted_out == "Y"`. Filter those out before the mail merge. If any duplicate of a person opted out, the merged record is "Y", so the whole person is excluded.
- **ZIP+4 handling:** I also accept a 4-digit prefix before the hyphen (for example, `2139-4307`), so Excel-mangled ZIP+4 values get the leading zero restored. Strict 5-4 matching would reject those.
- **Unparseable `updated` values** are treated as the oldest possible date.
